"""Prepend a "generated, do not edit" header to every Python file under a directory.

Run by openapi-python-client as a post hook (see ``openapi-client.yaml``) so the
generated client is recognizable to readers, reviewers and tooling.
"""

import sys
from pathlib import Path

HEADER = (
    "# Code generated by openapi-python-client from api/external/endoflife.yaml. DO NOT EDIT.\n"
)


def mark(root: Path) -> int:
    """Add the generated-code header to each ``.py`` file below ``root``.

    Files that already start with the header are left alone, so the hook is idempotent.

    Args:
        root: Directory holding the generated package.

    Returns:
        The number of files that were changed.
    """
    changed = 0
    for path in sorted(root.rglob("*.py")):
        text = path.read_text(encoding="utf-8")
        if not text.startswith(HEADER):
            path.write_text(HEADER + text, encoding="utf-8")
            changed += 1
    return changed


def main(argv: list[str]) -> int:
    """Mark the directory given as the only argument.

    Args:
        argv: Command-line arguments, without the program name.

    Returns:
        The process exit code.
    """
    if len(argv) != 1:
        print("usage: mark_generated.py <directory>", file=sys.stderr)
        return 2
    mark(Path(argv[0]))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
